import { getPrintInfo, decorateWorldToPdf } from '@/api/system'

/** 扁平化 getPrintInfo 返回的打印树 */
export function flattenPrintTemplates(list = []) {
  const result = []
  const walk = (items) => {
    (items || []).forEach((item) => {
      if (item?.templateCode) {
        result.push(item)
      }
      if (item?.sonList?.length) {
        walk(item.sonList)
      }
    })
  }
  walk(list)
  return result
}

/** 匹配「问题告知书 / 驳回告知书」类模板 */
export function pickRejectNoticeTemplate(list = []) {
  const flat = flattenPrintTemplates(list)
  return flat.find((item) => {
    const name = item.printTemplateName || ''
    return (
      name.includes('问题告知书') ||
      name.includes('驳回告知书') ||
      (name.includes('告知书') && name.includes('驳回'))
    )
  })
}

/**
 * 自动下载驳回问题告知书（备案申请节点 busCode 08033613 配置的模板）
 * @returns {Promise<boolean>} 是否已成功触发下载
 */
export async function downloadRejectNotice({
  maintenanceProjectId,
  busCodeList = ['08033613'],
  filterPrintList,
  sourceIdFallback
}) {
  if (!maintenanceProjectId) {
    return false
  }
  const res = await getPrintInfo({ maintenanceProjectId, busCodeList })
  let data = res.data || []
  if (typeof filterPrintList === 'function') {
    data = await filterPrintList(data)
  }
  const item = pickRejectNoticeTemplate(data)
  if (!item) {
    return false
  }
  const pdfRes = await decorateWorldToPdf({
    sourceId: item.sourceId || sourceIdFallback || maintenanceProjectId,
    templateCode: item.templateCode,
    extraParameters: item.extraParameters
  })
  window.open(`${window.origin}${pdfRes.data}`)
  return true
}

