async autoDownloadRejectNotice() {
  try {
    return await downloadRejectNotice({
      maintenanceProjectId: this.getId(),
      filterPrintList: this.isPrintItemHide,
      sourceIdFallback: this.getId()
    })
  } catch (err) {
    console.error('autoDownloadRejectNotice', err)
    return false
  }
},
async getRollbackMsg(msg) {
  if (msg && msg.includes('驳回')) { // 如果/estate/maintainproject/getInfo接口里返回了驳回相关的信息才会展示
    const downloaded = await this.autoDownloadRejectNotice()
    const tip = downloaded
      ? '问题告知书已自动下载，请查收浏览器下载/预览窗口。'
      : '未能自动下载问题告知书，请在「备案申请」步骤的打印菜单中手动打印。'
    this.$alert(`
    <span>${msg}<b style='position: absolute;color: red;bottom: -44px;left: 0;'>${tip}</b></span>
    `, '确认信息', {
      confirmButtonText: '确定',
      dangerouslyUseHTMLString: true
    })
      .then(() => { })
      .catch(() => { })
  }
},
async handleRejectSuccess() {
  await this.autoDownloadRejectNotice()
